// ---- helpers ---------------------------------------------------------------
// Settings come from the container environment (ai/.env)
const setting = (name, fallback) => {
    const value = $env[name];
    return value === undefined || value === '' ? fallback : String(value);
};
const seconds = (name, fallback) => {
    const value = Number(setting(name, fallback));
    return (Number.isFinite(value) && value >= 0 ? value : fallback) * 1000;
};
// InfluxDB CSV (header row, no annotations) → array of objects
function parseCsv(text) {
    const rows = [];
    let row = [], field = '', quoted = false;
    for (let i = 0; i < text.length; i++) {
        const c = text[i];
        if (quoted) {
            if (c === '"' && text[i + 1] === '"') { field += '"'; i++; }
            else if (c === '"') quoted = false;
            else field += c;
        } else if (c === '"') quoted = true;
        else if (c === ',') { row.push(field); field = ''; }
        else if (c === '\r' || c === '\n') {
            if (c === '\r' && text[i + 1] === '\n') i++;
            row.push(field); field = '';
            if (row.some((v) => v !== '')) rows.push(row);
            row = [];
        } else field += c;
    }
    if (field !== '' || row.length) { row.push(field); if (row.some((v) => v !== '')) rows.push(row); }
    const out = [];
    let header = null;
    for (const r of rows) {
        if (r[1] === 'result' && r[2] === 'table') { header = r; continue; }
        if (header) out.push(Object.fromEntries(header.map((h, i) => [h, r[i]])));
    }
    return out;
}
// Line protocol escaping
const tag = (v) => String(v).replace(/[\\, =]/g, (c) => '\\' + c);
const str = (v) => '"' + String(v).replace(/[\\"]/g, (c) => '\\' + c) + '"';
const esc = (v) => String(v).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const fmt = (t) => (t === null || t === undefined || Number.isNaN(t) ? '–' : (Math.round(t * 10) / 10).toFixed(1) + ' °C');
const minutes = (ms) => Math.max(0, Math.round(ms / 60000));
const label = (u) => (u.name || u.id) + (u.location ? ' (' + u.location + ')' : '');
// A time as people read it, in the project's timezone (TZ)
const when = (t) => DateTime.fromMillis(typeof t === 'number' ? t : Date.parse(t), { zone: setting('GENERIC_TIMEZONE', 'UTC') })
    .toFormat('yyyy-MM-dd HH:mm ZZZZ');
// The ack link carries a signature, so only links from an alert work
const crypto = require('crypto');
const sign = (device, excursion) => crypto.createHmac('sha256', setting('ACK_SECRET', ''))
    .update(device + '|' + excursion).digest('hex').slice(0, 32);

// ---- evaluate ----------------------------------------------------------------
// Runs every minute (and on POST /webhook/coldchain/check). Stateless: the
// excursions so far are read back from InfluxDB (coldchain_event), so a
// restart or an acknowledgement arriving mid-run loses nothing.
//
// For each unit in units.json:
//   problem    temperature outside [min, max], or no reading for OFFLINE_AFTER
//   start      first run that sees a problem with no open excursion
//   alert      problem has lasted ALERT_DELAY          → email ALERT_EMAIL_TO
//   escalate   alerted, not acknowledged for ESCALATE_AFTER → ESCALATION_EMAIL_TO
//   resolve    back in range                            → email whoever was told
const ALERT_DELAY = seconds('ALERT_DELAY', 900);
const ESCALATE_AFTER = seconds('ESCALATE_AFTER', 1800);
const OFFLINE_AFTER = seconds('OFFLINE_AFTER', 600);
const ALERT_TO = setting('ALERT_EMAIL_TO', '');
const ESCALATION_TO = setting('ESCALATION_EMAIL_TO', '');
const BASE_URL = setting('N8N_WEBHOOK_URL', 'http://localhost:5678/').replace(/\/?$/, '/');

const units = $('Parse units').first().json.units;
if (!Array.isArray(units)) throw new Error('units.json must be a JSON array of units');

const now = Date.now();
const latest = {};
for (const r of parseCsv($('Query readings').first().json.data || '')) {
    latest[r.device] = latest[r.device] || {};
    latest[r.device][r.sensor] = { time: Date.parse(r._time), value: Number(r._value) };
}
// Excursions per device: { id, start, types: {type: time} }
const excursions = {};
for (const r of parseCsv($('Query excursions').first().json.data || '')) {
    const byId = (excursions[r.device] = excursions[r.device] || {});
    const ex = (byId[r.excursion] = byId[r.excursion] || { id: r.excursion, start: Date.parse(r.excursion), types: {} });
    ex.types[r.type] = Date.parse(r._time);
}

const lines = [];
const notifications = [];
const summary = [];

for (const u of units) {
    if (!u || !u.id || !Number.isFinite(u.min) || !Number.isFinite(u.max)) {
        throw new Error('units.json: every unit needs an id and numeric min and max: ' + JSON.stringify(u));
    }
    const reading = (latest[u.id] || {}).temperature;
    const door = (latest[u.id] || {}).door;
    const temperature = reading ? reading.value : null;
    const range = u.min + '–' + u.max + ' °C';

    // What is wrong now, if anything
    let problem = null;
    if (!reading || now - reading.time > OFFLINE_AFTER) {
        problem = { kind: 'offline', text: reading
            ? 'no reading for ' + minutes(now - reading.time) + ' min (last ' + fmt(reading.value) + ')'
            : 'no reading in the last 24 h' };
    } else if (temperature > u.max) {
        problem = { kind: 'high', text: fmt(temperature) + ', above ' + u.max + ' °C' };
    } else if (temperature < u.min) {
        problem = { kind: 'low', text: fmt(temperature) + ', below ' + u.min + ' °C' };
    }
    if (problem && door && door.value === 1) problem.text += '; door open';

    const open = Object.values(excursions[u.id] || {})
        .filter((e) => !('resolve' in e.types))
        .sort((a, b) => b.start - a.start)[0];
    const event = (ex, type, message, time = now, extra = '') => lines.push(
        'coldchain_event,device=' + tag(u.id) + ',excursion=' + tag(ex.id) + ',type=' + type
        + ' message=' + str(message) + (temperature !== null ? ',temperature=' + temperature : '') + extra + ' ' + time);
    const ackUrl = (ex) => BASE_URL + 'webhook/coldchain/ack?device=' + encodeURIComponent(u.id)
        + '&excursion=' + encodeURIComponent(ex.id) + '&token=' + sign(u.id, ex.id);
    const notify = (level, to, subject, intro, ex, withAck) => {
        if (!to) return;
        const rows = [
            ['Unit', label(u)], ['Now', problem ? problem.text : fmt(temperature)], ['Limits', range],
            ['Since', when(ex.start)], ['Duration', minutes(now - ex.start) + ' min'],
        ];
        const ack = withAck ? ackUrl(ex) : null;
        notifications.push({
            level, to, subject,
            text: intro + '\n\n' + rows.map(([k, v]) => k + ': ' + v).join('\n')
                + (ack ? '\n\nAcknowledge and record the corrective action:\n' + ack : ''),
            html: '<p>' + esc(intro) + '</p><table cellpadding="4">'
                + rows.map(([k, v]) => '<tr><td><b>' + esc(k) + '</b></td><td>' + esc(v) + '</td></tr>').join('')
                + '</table>'
                + (ack ? '<p><a href="' + esc(ack) + '">Acknowledge and record the corrective action</a></p>' : ''),
        });
    };

    let ex = open;
    if (problem && !ex) {
        // An excursion starts at its last good reading's successor: the reading
        // that is out of range, or the last one seen before the unit went quiet
        const start = reading ? Math.min(reading.time, now) : now;
        ex = { id: new Date(start).toISOString(), start, types: {} };
        event(ex, 'start', problem.text, start);
        ex.types.start = start;
    }
    if (!problem && ex) {
        const told = [];
        if ('alert' in ex.types) told.push(ALERT_TO);
        if ('escalate' in ex.types) told.push(ESCALATION_TO);
        event(ex, 'resolve', 'back in range at ' + fmt(temperature) + ' after ' + minutes(now - ex.start) + ' min');
        if (told.length) {
            notify('resolved', told.filter(Boolean).join(','),
                '[Cold chain] Resolved: ' + label(u) + ' back in range after ' + minutes(now - ex.start) + ' min',
                label(u) + ' is back within ' + range + '.' + ('ack' in ex.types ? '' : ' Nobody has acknowledged it yet: record the corrective action.'),
                ex, !('ack' in ex.types));
        }
        ex = null;
    }
    if (problem && ex) {
        if (!('alert' in ex.types) && now - ex.start >= ALERT_DELAY) {
            event(ex, 'alert', problem.text);
            ex.types.alert = now;
            notify('alert', ALERT_TO,
                '[Cold chain] ALERT: ' + label(u) + ' ' + problem.text,
                label(u) + ' has been out of range (' + range + ') for ' + minutes(now - ex.start) + ' min.', ex, true);
        } else if ('alert' in ex.types && !('ack' in ex.types) && !('escalate' in ex.types)
                   && now - ex.types.alert >= ESCALATE_AFTER) {
            event(ex, 'escalate', problem.text);
            ex.types.escalate = now;
            notify('escalate', [ESCALATION_TO, ALERT_TO].filter(Boolean).join(','),
                '[Cold chain] ESCALATION: ' + label(u) + ' out of range for ' + minutes(now - ex.start) + ' min, not acknowledged',
                'Nobody has acknowledged this alert in ' + minutes(now - ex.types.alert) + ' min.', ex, true);
        }
    }

    // Current state, and the unit's limits, for Grafana
    let state = 'ok';
    if (problem) {
        state = 'ack' in ex.types ? 'acknowledged' : 'escalate' in ex.types ? 'escalated'
            : 'alert' in ex.types ? 'alerted' : problem.kind === 'offline' ? 'offline' : 'excursion';
    }
    lines.push('coldchain_status,device=' + tag(u.id) + ' state=' + str(state)
        + ',in_range=' + (problem ? 0 : 1) + (temperature !== null ? ',temperature=' + temperature : '') + ' ' + now);
    lines.push('coldchain_limit,device=' + tag(u.id) + ' min=' + u.min + ',max=' + u.max + ' ' + now);
    summary.push({ device: u.id, state, temperature, excursion: ex ? ex.id : null });
}

return [
    ...notifications.map((n) => ({ json: { kind: 'notify', ...n } })),
    { json: { kind: 'write', lines: lines.join('\n'), summary: { checked_at: new Date(now).toISOString(), notifications: notifications.length, units: summary } } },
];
